from __future__ import annotations

import asyncio
import json
from dataclasses import asdict, dataclass, field
from typing import Annotated, Any, Protocol

from fastapi import APIRouter, Depends, HTTPException, Request

from ..security.audit_log import audit_log
from .consent import list_consents

MAX_BODY_BYTES = 256 * 1024


@dataclass(frozen=True)
class RetainedRecord:
    category: str
    reason: str


@dataclass(frozen=True)
class EraseResult:
    erased: list[str] = field(default_factory=list)
    retained: list[RetainedRecord] = field(default_factory=list)


@dataclass(frozen=True)
class Nominee:
    name: str
    relation: str
    contact: str


class DsrAdapter(Protocol):
    # Identity verification — must confirm the requester IS the data principal.
    # Returns the verified data principal ID, or None.
    async def verify_requester_identity(self, request: Request) -> str | None: ...

    # Aggregate everything you hold about this person. Used by §11 access.
    async def collect_personal_data(self, data_principal_id: str) -> dict[str, Any]: ...

    # Apply a correction set provided by the data principal. Used by §12 correction.
    async def apply_corrections(self, data_principal_id: str, changes: dict[str, Any]) -> None: ...

    # Soft-delete or anonymize personal data. Used by §12 erasure.
    # Returns a list of records flagged for deletion + records retained under legal hold.
    async def erase_or_anonymize(self, data_principal_id: str) -> EraseResult: ...

    # Record a grievance for the grievance officer (§13). Returns the ticket ID.
    async def record_grievance(self, data_principal_id: str, message: str) -> str: ...

    # Record a nomination (§14).
    async def record_nomination(self, data_principal_id: str, nominee: Nominee) -> None: ...


_adapter: DsrAdapter | None = None


def set_dsr_adapter(adapter: DsrAdapter) -> None:
    global _adapter
    _adapter = adapter


def _require_adapter() -> DsrAdapter:
    if _adapter is None:
        raise RuntimeError('secure-by-design: DsrAdapter not configured.')
    return _adapter


async def _require_data_principal(request: Request) -> str:
    data_principal_id = await _require_adapter().verify_requester_identity(request)
    if data_principal_id is None:
        raise HTTPException(status_code=401, detail='identity_verification_required')
    return data_principal_id


async def _json_body(request: Request) -> dict[str, Any]:
    # FastAPI has no body limit of its own, so count bytes while reading.
    chunks: list[bytes] = []
    size = 0
    async for chunk in request.stream():
        size += len(chunk)
        if size > MAX_BODY_BYTES:
            raise HTTPException(status_code=413, detail='body_too_large')
        chunks.append(chunk)
    if size == 0:
        return {}
    try:
        body = json.loads(b''.join(chunks))
    except (ValueError, RecursionError) as e:
        raise HTTPException(status_code=400, detail='invalid_json') from e
    return body if isinstance(body, dict) else {}


DataPrincipal = Annotated[str, Depends(_require_data_principal)]


def dsr_router() -> APIRouter:
    router = APIRouter()

    # DPDP §11 — Right to access information about personal data
    @router.get('/access')
    async def access(dp_id: DataPrincipal) -> dict[str, Any]:
        data, consents = await asyncio.gather(
            _require_adapter().collect_personal_data(dp_id),
            list_consents(dp_id),
        )
        await audit_log.event('dsr.access', actor=dp_id, target=dp_id)
        return {'personalData': data, 'consentHistory': consents}

    # DPDP §12 — Right to correction, completion, updating
    @router.post('/correct')
    async def correct(dp_id: DataPrincipal, request: Request) -> dict[str, Any]:
        changes = (await _json_body(request)).get('changes')
        if not isinstance(changes, dict):
            raise HTTPException(status_code=400, detail='changes_required')
        await _require_adapter().apply_corrections(dp_id, changes)
        await audit_log.event('dsr.correct', actor=dp_id, target=dp_id, attrs={'fields': list(changes)})
        return {'ok': True}

    # DPDP §12 — Right to erasure
    @router.post('/erase')
    async def erase(dp_id: DataPrincipal) -> dict[str, Any]:
        result = await _require_adapter().erase_or_anonymize(dp_id)
        await audit_log.event(
            'dsr.erase',
            actor=dp_id,
            target=dp_id,
            attrs={'erasedCount': len(result.erased), 'retainedCount': len(result.retained)},
        )
        # Communicate retention reasons honestly — DPDP allows retention only for
        # legal compliance or specified purposes. The user expects to know.
        return asdict(result)

    # DPDP §13 — Right to grievance redressal
    @router.post('/grievance', status_code=201)
    async def grievance(dp_id: DataPrincipal, request: Request) -> dict[str, Any]:
        message = (await _json_body(request)).get('message')
        if not isinstance(message, str) or not 0 < len(message) <= 5000:
            raise HTTPException(status_code=400, detail='message_required')
        ticket_id = await _require_adapter().record_grievance(dp_id, message)
        await audit_log.event('dsr.grievance', actor=dp_id, target=dp_id, attrs={'ticketId': ticket_id})
        # TODO(user): notify the grievance officer via your incident channel.
        return {'ticketId': ticket_id}

    # DPDP §14 — Right to nominate
    @router.post('/nominate')
    async def nominate(dp_id: DataPrincipal, request: Request) -> dict[str, Any]:
        body = await _json_body(request)
        name, relation, contact = body.get('name'), body.get('relation'), body.get('contact')
        if not (name and relation and contact) or not all(isinstance(v, str) for v in (name, relation, contact)):
            raise HTTPException(status_code=400, detail='nominee_fields_required')
        await _require_adapter().record_nomination(dp_id, Nominee(name=name, relation=relation, contact=contact))
        await audit_log.event('dsr.nominate', actor=dp_id, target=dp_id)
        return {'ok': True}

    return router


